e_26.txt', 'r') as f:\n    content_86 = f.read()\nwith open('/app/resources/treasury_bulletin_1987_03_page_24.txt', 'r') as f:\n    content_87 = f.read()\nwith open('/app/resources/treasury_bulletin_1988_03_page_36.txt', 'r') as f:\n    content_88 = f.read()\n\n# Extract data\nprint(\"1984:\")\ndata_1984 = get_full_year_data(content_85, '1984')\nprint(data_1984)\n\nprint(\"\\n1985:\")\ndata_1985 = get_full_year_data(content_86, '1985')\nprint(data_1985)\n\nprint(\"\\n1986:\")\ndata_1986 = get_full_year_data(content_87, '1986')\nprint(data_1986)\n\nprint(\"\\n1987:\")\ndata_1987 = get_full_year_data(content_88, '1987')\nprint(data_1987)\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
